import { NextRequest, NextResponse } from "next/server";
import crypto from "crypto";
import { createAdminClient } from "@/lib/supabase/admin";

export const dynamic = "force-dynamic";

/**
 * Verifies Svix signature generated by Resend webhooks.
 * Headers: svix-id, svix-timestamp, svix-signature
 * Secret format: whsec_<base64> or raw string
 */
function verifySvixSignature(
  payload: string,
  headers: { id: string | null; timestamp: string | null; signature: string | null },
  secret: string
): boolean {
  if (!headers.id || !headers.timestamp || !headers.signature) {
    return false;
  }

  // Prevent replay attacks (allow up to 10 minutes tolerance)
  const timestamp = parseInt(headers.timestamp, 10);
  if (isNaN(timestamp)) return false;
  const now = Math.floor(Date.now() / 1000);
  if (Math.abs(now - timestamp) > 600) {
    return false;
  }

  // Strip whsec_ prefix if present
  let rawSecret: Buffer;
  try {
    const cleanSecret = secret.startsWith("whsec_") ? secret.slice(6) : secret;
    rawSecret = Buffer.from(cleanSecret, "base64");
  } catch {
    rawSecret = Buffer.from(secret, "utf8");
  }

  const toSign = `${headers.id}.${headers.timestamp}.${payload}`;
  const expectedHmac = crypto.createHmac("sha256", rawSecret).update(toSign).digest("base64");

  // svix-signature may contain multiple space-separated signatures: "v1,abc v1,xyz"
  const passedSignatures = headers.signature.split(" ");
  for (const sig of passedSignatures) {
    const [version, signatureValue] = sig.split(",");
    if (version === "v1" && signatureValue) {
      const bufSig = Buffer.from(signatureValue);
      const bufExp = Buffer.from(expectedHmac);
      if (bufSig.length === bufExp.length && crypto.timingSafeEqual(bufSig, bufExp)) {
        return true;
      }
    }
  }

  return false;
}

export async function POST(req: NextRequest) {
  try {
    const rawBody = await req.text();
    const svixId = req.headers.get("svix-id");
    const svixTimestamp = req.headers.get("svix-timestamp");
    const svixSignature = req.headers.get("svix-signature");

    const webhookSecret = process.env.RESEND_WEBHOOK_SECRET;

    // Verify signature if secret is configured
    if (webhookSecret) {
      const isValid = verifySvixSignature(
        rawBody,
        { id: svixId, timestamp: svixTimestamp, signature: svixSignature },
        webhookSecret
      );

      if (!isValid) {
        console.warn("[Resend Webhook] Signature verification failed");
        return NextResponse.json({ error: "Invalid webhook signature" }, { status: 401 });
      }
    }

    const event = JSON.parse(rawBody);
    const eventType: string = event.type || "";
    const emailData = event.data || {};
    const emailId: string | undefined = emailData.email_id || emailData.id;
    const recipient: string | undefined = Array.isArray(emailData.to) ? emailData.to[0] : emailData.to;

    let targetEmailStatus: "delivered" | "bounced" | "complained" | null = null;
    if (eventType === "email.delivered") {
      targetEmailStatus = "delivered";
    } else if (eventType === "email.bounced") {
      targetEmailStatus = "bounced";
    } else if (eventType === "email.complained") {
      targetEmailStatus = "complained";
    }

    if (!targetEmailStatus) {
      return NextResponse.json({ received: true, ignored: true, type: eventType });
    }

    const adminClient = createAdminClient();

    // 1. Update workspace_invitations
    if (emailId) {
      try {
        await adminClient
          .from("workspace_invitations")
          .update({
            email_status: targetEmailStatus,
            updated_at: new Date().toISOString(),
          })
          .eq("resend_message_id", emailId);
      } catch (e) {
        console.warn("[Resend Webhook] workspace_invitations update notice:", e);
      }
    } else if (recipient) {
      try {
        await adminClient
          .from("workspace_invitations")
          .update({
            email_status: targetEmailStatus,
            updated_at: new Date().toISOString(),
          })
          .eq("email", recipient.toLowerCase().trim())
          .eq("status", "pending");
      } catch (e) {
        console.warn("[Resend Webhook] recipient update notice:", e);
      }
    }

    // 2. Update email_log
    if (emailId) {
      try {
        await adminClient
          .from("email_log")
          .update({
            status: targetEmailStatus,
          })
          .eq("resend_message_id", emailId);
      } catch (e) {
        console.warn("[Resend Webhook] email_log update notice:", e);
      }
    }

    return NextResponse.json({
      received: true,
      emailId,
      status: targetEmailStatus,
    });
  } catch (err: unknown) {
    const msg = err instanceof Error ? err.message : String(err);
    console.error("[Resend Webhook Error]:", msg);
    return NextResponse.json({ error: "Failed to process webhook" }, { status: 400 });
  }
}
